// Row-82 unit tests: the fetch/verify/provenance library exercised WITHOUT public
// network. A local bun.serve fixture binds port 0 (OS-assigned ephemeral — the
// PORT RULE's guarantee that no fixed/common port is ever touched) on 127.0.0.1
// over REAL TLS: a throwaway CA + server cert are generated by
// test/fetch.proofs.sh, which runs bun with NODE_EXTRA_CA_CERTS pointed at that
// CA. The library code path under test is byte-for-byte the production one —
// HTTPS-only enforcement, allow-list, redirect re-policy, digest verification —
// and TLS verification is NEVER weakened anywhere (P-17): no bypass flags, no
// trust-disabling variables inside this file. The only seams are
// FetchOptions.allowedHosts (lock-subset-checked) and SignatureSpec.run
// (test-scripted gate outcome).
//
// Run TARGETED (row 102 owns the full suite on this host):
//   bash packages/setup/test/fetch.proofs.sh
// or, with certs already generated:
//   cd packages/setup && R82_CA_DIR=<cadir> NODE_EXTRA_CA_CERTS=<cadir>/ca.pem bun test test/fetch.test.ts
//
// SELF-SKIP POSTURE (FIX3, controller decision after r83-fix2): a bare `bun test`
// without R82_CA_DIR exported skips exactly the real-TLS cases — visibly, with the
// env var named in each skip reason — so the row-102 combined baseline stays honest.
// The proof runners (fetch.proofs.sh, combined.proofs.sh) export the env and get the
// full execute-and-pass coverage. Setting R82_CA_DIR without a usable cert dir is a
// loud error, never a silent skip.

import { describe, it, expect, beforeAll, afterAll } from "bun:test"
import { createHash } from "node:crypto"
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  existsSync,
  readdirSync,
  copyFileSync,
  rmSync,
} from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { fetchArtifact, resolveArtifact, type FetchOptions } from "../src/fetch.ts"
import { computeFileDigest, fileMatchesDigest, macSignatureCheck, parseExpectedDigest } from "../src/verify.ts"
import { readProvenanceRecords } from "../src/provenance.ts"
import { loadLock, validateLock, type LockFile } from "../src/lockfile.ts"

const PAYLOAD = new TextEncoder().encode("swarm-fixture-artifact-bytes-v1\n") // 34 bytes
const WRONG = new TextEncoder().encode("swarm-fixture-artifact-bytes-TAMPERED!") // same length, different bytes
const BIG = new Uint8Array(5000).fill(0x41)
const sha256Hex = (bytes: Uint8Array): string => createHash("sha256").update(bytes).digest("hex")

// ---- fixture server (real TLS, port 0, loopback) --------------------------------------

const CA_DIR = process.env.R82_CA_DIR ?? ""
const certsAvailable = CA_DIR !== "" && existsSync(join(CA_DIR, "server.key")) && existsSync(join(CA_DIR, "chain.pem"))

let server: { port: number; stop(force?: boolean): void } | null = null
let hits: Record<string, number> = {}
const portOf = (): number => (server ? server.port : 0)

function respond(status: number, body?: Uint8Array, location?: string): Response {
  const headers: Record<string, string> = {}
  if (location !== undefined) headers.location = location
  return new Response(body ? body.slice() : null, { status, headers })
}

// Source-run lock posture: paths.resolveProgramDir() falls back to import.meta.dir
// of paths.ts (= src/) when no lock sits beside the executable, so loadLock() in a
// `bun test` process looks for src/tools.lock.json. Row 81's own proofs only used
// the COMPILED binary (lock beside execPath), hiding this; row 106 finalises the
// posture. The harness stages a temporary copy for the duration of this suite and
// removes it after — the tracked package root copy is never touched.
const SHIPPED_LOCK = join(import.meta.dir, "..", "tools.lock.json")
const SRC_LOCK = join(import.meta.dir, "..", "src", "tools.lock.json")
let stagedLock = false

beforeAll(() => {
  if (!existsSync(SRC_LOCK) && existsSync(SHIPPED_LOCK)) {
    copyFileSync(SHIPPED_LOCK, SRC_LOCK)
    stagedLock = true
  }
})

afterAll(() => {
  if (stagedLock) rmSync(SRC_LOCK, { force: true })
})

beforeAll(() => {
  if (!certsAvailable) return
  hits = {}
  server = Bun.serve({
    port: 0, // ephemeral by PORT RULE; never a fixed/common port
    hostname: "127.0.0.1",
    tls: { key: Bun.file(join(CA_DIR, "server.key")), cert: Bun.file(join(CA_DIR, "chain.pem")) },
    async fetch(req: Request): Promise<Response> {
      const path = new URL(req.url).pathname
      hits[path] = (hits[path] ?? 0) + 1
      const n = hits[path]
      if (path === "/artifact") return respond(200, PAYLOAD)
      if (path === "/wrong") return respond(200, WRONG)
      if (path === "/big") return respond(200, BIG)
      if (path === "/stream-chunked") {
        // delayed enqueues force chunked transfer (no Content-Length) -> mid-stream cap path
        return new Response(
          new ReadableStream({
            async start(controller) {
              controller.enqueue(BIG.subarray(0, 2500))
              await new Promise((r) => setTimeout(r, 30))
              controller.enqueue(BIG.subarray(2500))
              controller.close()
            },
          }),
        )
      }
      if (path === "/redirect-ok") return respond(302, undefined, `https://127.0.0.1:${portOf()}/artifact`)
      if (path === "/redirect-bad-host") return respond(302, undefined, "https://evil.example/artifact")
      if (path === "/redirect-downgrade") return respond(302, undefined, `http://127.0.0.1:${portOf()}/artifact`)
      if (path === "/flaky") return n < 2 ? respond(503) : respond(200, PAYLOAD)
      if (path === "/always500") return respond(500)
      if (path === "/gone") return respond(404)
      if (path === "/hangs") return new Promise<Response>(() => undefined) // never resolves -> client timeout
      return respond(418)
    },
  })
})

afterAll(() => {
  server?.stop(true) // force: kills the never-resolving /hangs handler
})

/** Fail loudly when R82_CA_DIR was set but the fixture is not actually runnable. */
function requireFixture(): void {
  if (!certsAvailable || !server)
    throw new Error("fixture not running: run via test/fetch.proofs.sh (sets R82_CA_DIR + NODE_EXTRA_CA_CERTS)")
}

/** FIX3 self-skip: the real-TLS cases need a CA generated by a proof runner BEFORE
 *  process launch (NODE_EXTRA_CA_CERTS is read at startup). Without R82_CA_DIR they
 *  skip WITH A REASON naming the env var and the runners — an honest line in bun's
 *  summary, never a silent pass. With it set, they execute (requireFixture above
 *  turns a half-set env into a loud failure). */
const TLS_SKIP_REASON = "requires R82_CA_DIR; run via fetch.proofs.sh or combined.proofs.sh for real-TLS coverage"
const tlsReady = CA_DIR !== ""
function itTls(name: string, fn: () => void | Promise<void>): void {
  if (!tlsReady) it.skip(`[real-TLS] ${name} (${TLS_SKIP_REASON})`, () => undefined)
  else it(name, fn)
}

// ---- locks ------------------------------------------------------------------------------

/** Synthetic validated lock whose only allow-listed host is the loopback fixture.
 *  Component set mirrors the register's seven PC-CMP ids so validateLock passes. */
function fixtureLock(): LockFile {
  const url = `https://127.0.0.1:${portOf()}/artifact`
  const parsed = {
    schemaVersion: 1,
    version: "fixture-lock-v1",
    // ghcr.io appears only so the image refs satisfy validateLock (D-16 alias check);
    // no test ever fetches an image through this library (dockerd owns pulls).
    hosts: ["127.0.0.1", "ghcr.io"],
    components: {
      runtime: {
        colima: { url, version: "c1", size: PAYLOAD.length, sha256: sha256Hex(PAYLOAD) },
        lima: { url, version: "l1", size: PAYLOAD.length, sha256: sha256Hex(PAYLOAD) },
        guest_image: { url: null, version: null, sha256: null },
      },
      node: { url, version: "v9.9.9", size: PAYLOAD.length, tarball_sha256: sha256Hex(PAYLOAD) },
      graft: {
        package: "@nanonets/graft",
        url,
        version: "0.0.1",
        size: PAYLOAD.length,
        integrity: `sha512-${createHash("sha512").update(PAYLOAD).digest("base64")}`,
      },
      rtk: {
        url: `https://127.0.0.1:${portOf()}/redirect-ok`,
        version: "v0.0.1",
        size: PAYLOAD.length,
        sha256: sha256Hex(PAYLOAD),
      },
      obsidian: {
        url: `https://127.0.0.1:${portOf()}/wrong`,
        version: "v0.0.1",
        size: WRONG.length,
        dmg_sha256: sha256Hex(PAYLOAD),
        team_id: null,
      },
      searxng: { image: `ghcr.io/x/x@sha256:${"0".repeat(64)}` },
      firecrawl: { api_image: `ghcr.io/x/y@sha256:${"0".repeat(64)}` },
    },
  }
  const result = validateLock(parsed)
  if (!result.ok) throw new Error(`fixture lock rejected by the row-81 validator: ${result.error}`)
  return result.lock
}

// ---- throwaway HOME per test --------------------------------------------------------------

function freshHome(): string {
  const home = mkdtempSync(join(tmpdir(), "r82-test-"))
  process.env.HOME = home
  return home
}

function baseOpts(home: string, extra: Partial<FetchOptions> = {}): FetchOptions {
  return {
    allowedHosts: ["127.0.0.1"],
    destDir: join(home, ".swarm", "tools", "test"),
    stagingDir: join(home, ".swarm", "tmp"),
    provenancePath: join(home, ".swarm", "setup", "provenance.jsonl"),
    timeoutMs: 5000,
    retryDelayMs: 10,
    ...extra,
  }
}

function stagingLeftovers(home: string): string[] {
  const dir = join(home, ".swarm", "tmp")
  return existsSync(dir) ? readdirSync(dir) : []
}

// ---- tests ---------------------------------------------------------------------------------

describe("resolveArtifact (pin resolution from the REAL shipped lock, zero network)", () => {
  it("node pin matches row 80 values verbatim (url, sha256, size)", () => {
    const loaded = loadLock()
    expect(loaded.ok).toBe(true)
    if (!loaded.ok) return
    const r = resolveArtifact(loaded.lock, "node")
    expect(r.ok).toBe(true)
    if (!r.ok) return
    expect(r.artifact.url).toBe("https://nodejs.org/dist/v24.22.0/node-v24.22.0-darwin-arm64.tar.gz")
    expect(r.artifact.expected.hex).toBe("6a9724d9b50a5f22b4816cded441b5a8d9ddae546191a5e5b7efa5a5e2ee26d5")
    expect(r.artifact.expectedSizeBytes).toBe(53049576)
    expect(r.artifact.host).toBe("nodejs.org")
  })

  it("runtime is ambiguous without an explicit artifact id; colima resolves when named", () => {
    const loaded = loadLock()
    if (!loaded.ok) throw new Error("shipped lock must validate")
    const ambiguous = resolveArtifact(loaded.lock, "runtime")
    expect(ambiguous.ok).toBe(false)
    if (!ambiguous.ok) expect(ambiguous.message).toContain("pass the artifact id explicitly")
    const colima = resolveArtifact(loaded.lock, "runtime", "colima")
    expect(colima.ok).toBe(true)
    if (!colima.ok) return
    expect(colima.artifact.expected.hex).toBe("980ad8bf61a4ca370243f4cb41401a61276dcd2c2502bee7b9b86f9250169f34")
  })

  it("guest_image url is null -> NO_URL_PINNED, never fetched (D-13)", () => {
    const loaded = loadLock()
    if (!loaded.ok) throw new Error("shipped lock must validate")
    const r = resolveArtifact(loaded.lock, "runtime", "guest_image")
    expect(r.ok).toBe(false)
    if (!r.ok) expect(r.code).toBe("NO_URL_PINNED")
  })

  it("graft npm sha512 integrity parses to 128-hex; malformed integrity parses to null", () => {
    const loaded = loadLock()
    if (!loaded.ok) throw new Error("shipped lock must validate")
    const r = resolveArtifact(loaded.lock, "graft")
    expect(r.ok).toBe(true)
    if (!r.ok) return
    expect(r.artifact.expected.algorithm).toBe("sha512")
    expect(r.artifact.expected.hex).toHaveLength(128)
    expect(parseExpectedDigest("sha512-!!!not-base64!!!")).toBe(null)
  })
})

describe("host allow-list + HTTPS-only policy (P-18/P-17)", () => {
  itTls(
    "refuses a host outside the lock allow-list with REFUSED_HOST_DENIED naming the host, ZERO server hits",
    async () => {
      requireFixture()
      const home = freshHome()
      const before = hits["/artifact"] ?? 0
      const out = await fetchArtifact(fixtureLock(), "node", baseOpts(home, { allowedHosts: [] }))
      expect(out.ok === false && out.code).toBe("REFUSED_HOST_DENIED")
      expect(out.ok === false && out.message).toContain("127.0.0.1") // names the refused host
      expect(hits["/artifact"] ?? 0).toBe(before) // instrumented: nothing left the process
      expect(stagingLeftovers(home)).toEqual([])
    },
  )

  itTls("refuses an http:// URL even when its host IS allow-listed (HTTP downgrade refused)", async () => {
    requireFixture()
    const home = freshHome()
    const lock = fixtureLock()
    const downgraded: LockFile = {
      ...lock,
      components: {
        ...lock.components,
        node: { ...lock.components.node, url: `http://127.0.0.1:${portOf()}/artifact` },
      },
    }
    const out = await fetchArtifact(downgraded, "node", baseOpts(home))
    expect(out.ok === false && out.code).toBe("REFUSED_INSECURE_PROTOCOL")
  })

  itTls("the allowedHosts seam can only NARROW the lock list (widening rejects synchronously)", async () => {
    requireFixture()
    expect(fetchArtifact(fixtureLock(), "node", { allowedHosts: ["evil.example"] })).rejects.toThrow(/NARROW/)
  })
})

describe("download + verify-before-use (P-1 tamper)", () => {
  itTls("happy path over real TLS: fetched, bytes correct, staging empty, provenance recorded", async () => {
    requireFixture()
    const home = freshHome()
    const opts = baseOpts(home)
    const out = await fetchArtifact(fixtureLock(), "node", opts)
    expect(out.status).toBe("fetched")
    expect(readFileSync(out.destPath)).toEqual(PAYLOAD)
    expect(stagingLeftovers(home)).toEqual([])
    const prov = readProvenanceRecords(opts.provenancePath)
    expect(prov.length).toBe(1)
    expect(prov[0]?.outcome).toBe("fetched")
  })

  itTls("server serving wrong bytes -> HASH_MISMATCH; final never created; temp destroyed", async () => {
    requireFixture()
    const home = freshHome()
    const opts = baseOpts(home)
    const out = await fetchArtifact(fixtureLock(), "obsidian", opts) // pin expects PAYLOAD hash, /wrong serves WRONG bytes of equal size
    expect(out.ok === false && out.code).toBe("HASH_MISMATCH")
    expect(out.ok === false && out.message).toContain("aborting before use")
    expect(existsSync(join(home, ".swarm", "tools", "test"))).toBe(false) // final name never appeared
    expect(stagingLeftovers(home)).toEqual([])
    const prov = readProvenanceRecords(opts.provenancePath)
    expect(prov.length).toBe(1)
    expect(prov[0]?.outcome).toBe("failed")
    expect(prov[0]?.code).toBe("HASH_MISMATCH")
    expect(prov[0]?.observed).toBe(sha256Hex(WRONG)) // observed vs expected both on the record
    expect(prov[0]?.expected).toBe(sha256Hex(PAYLOAD))
  })

  itTls("byte count differing from the pinned size -> SIZE_EXCEEDED even when the hash would match", async () => {
    requireFixture()
    const home = freshHome()
    const lock = fixtureLock()
    const mispinned: LockFile = {
      ...lock,
      components: { ...lock.components, node: { ...lock.components.node, size: PAYLOAD.length + 1 } },
    }
    const out = await fetchArtifact(mispinned, "node", baseOpts(home))
    expect(out.ok === false && out.code).toBe("SIZE_EXCEEDED")
    expect(stagingLeftovers(home)).toEqual([])
  })

  itTls("Content-Length above the cap -> refused BEFORE the body is consumed", async () => {
    requireFixture()
    const home = freshHome()
    const lock = fixtureLock()
    const bigPin: LockFile = {
      ...lock,
      components: {
        ...lock.components,
        rtk: { url: `https://127.0.0.1:${portOf()}/big`, version: "v", size: 100, sha256: sha256Hex(BIG) },
      },
    }
    const out = await fetchArtifact(bigPin, "rtk", baseOpts(home, { destName: "early.bin" }))
    expect(out.ok === false && out.code).toBe("SIZE_EXCEEDED")
    expect(out.ok === false && out.message).toContain("Content-Length")
    expect(stagingLeftovers(home)).toEqual([])
  })

  itTls("chunked stream past the cap -> aborted MID-STREAM, temp removed", async () => {
    requireFixture()
    const home = freshHome()
    const lock = fixtureLock()
    const capped: LockFile = {
      ...lock,
      components: {
        ...lock.components,
        rtk: { url: `https://127.0.0.1:${portOf()}/stream-chunked`, version: "v", sha256: sha256Hex(BIG) },
      }, // no size pin
    }
    const out = await fetchArtifact(capped, "rtk", baseOpts(home, { absoluteCapBytes: 3000, destName: "mid.bin" }))
    expect(out.ok === false && out.code).toBe("SIZE_EXCEEDED")
    expect(out.ok === false && out.message).toContain("mid-stream")
    expect(stagingLeftovers(home)).toEqual([])
  })
})

describe("redirect re-policy on every hop (P-18)", () => {
  itTls("follows an in-list redirect and fetches the target", async () => {
    requireFixture()
    const home = freshHome()
    const out = await fetchArtifact(fixtureLock(), "rtk", baseOpts(home, { destName: "via-redirect.bin" })) // rtk pin -> /redirect-ok -> /artifact
    expect(out.status).toBe("fetched")
    if (out.status !== "fetched") return
    expect(readFileSync(out.destPath)).toEqual(PAYLOAD)
    expect(hits["/artifact"]).toBeGreaterThan(0) // the redirected hop really happened
  })

  itTls("refuses a redirect that leaves the allow-list, naming the off-list host", async () => {
    requireFixture()
    const home = freshHome()
    const lock = fixtureLock()
    const evil: LockFile = {
      ...lock,
      components: {
        ...lock.components,
        rtk: {
          url: `https://127.0.0.1:${portOf()}/redirect-bad-host`,
          version: "v",
          size: PAYLOAD.length,
          sha256: sha256Hex(PAYLOAD),
        },
      },
    }
    const out = await fetchArtifact(evil, "rtk", baseOpts(home))
    expect(out.ok === false && out.code).toBe("REFUSED_HOST_DENIED")
    expect(out.ok === false && out.message).toContain("evil.example")
  })

  itTls("refuses a redirect that downgrades to http://", async () => {
    requireFixture()
    const home = freshHome()
    const lock = fixtureLock()
    const downgrade: LockFile = {
      ...lock,
      components: {
        ...lock.components,
        rtk: {
          url: `https://127.0.0.1:${portOf()}/redirect-downgrade`,
          version: "v",
          size: PAYLOAD.length,
          sha256: sha256Hex(PAYLOAD),
        },
      },
    }
    const out = await fetchArtifact(downgrade, "rtk", baseOpts(home))
    expect(out.ok === false && out.code).toBe("REFUSED_INSECURE_PROTOCOL")
  })
})

describe("timeout + single backoff retry", () => {
  itTls("503 once then 200 -> fetched with attempts=2 (transient absorbed)", async () => {
    requireFixture()
    const home = freshHome()
    const lock = fixtureLock()
    const flaky: LockFile = {
      ...lock,
      components: {
        ...lock.components,
        rtk: {
          url: `https://127.0.0.1:${portOf()}/flaky`,
          version: "v",
          size: PAYLOAD.length,
          sha256: sha256Hex(PAYLOAD),
        },
      },
    }
    const out = await fetchArtifact(flaky, "rtk", baseOpts(home))
    expect(out.status).toBe("fetched")
    if (out.status !== "fetched") return
    expect(out.attempts).toBe(2)
  })

  itTls("persistent 5xx -> SERVER_ERROR after exactly 2 attempts", async () => {
    requireFixture()
    const home = freshHome()
    const lock = fixtureLock()
    const broken: LockFile = {
      ...lock,
      components: {
        ...lock.components,
        rtk: {
          url: `https://127.0.0.1:${portOf()}/always500`,
          version: "v",
          size: PAYLOAD.length,
          sha256: sha256Hex(PAYLOAD),
        },
      },
    }
    const out = await fetchArtifact(broken, "rtk", baseOpts(home))
    expect(out.ok === false && out.code).toBe("SERVER_ERROR")
    expect(out.ok === false && out.attempts).toBe(2)
  })

  itTls("404 is permanent: single attempt, FETCH_FAILED", async () => {
    requireFixture()
    const home = freshHome()
    const lock = fixtureLock()
    const gone: LockFile = {
      ...lock,
      components: {
        ...lock.components,
        rtk: {
          url: `https://127.0.0.1:${portOf()}/gone`,
          version: "v",
          size: PAYLOAD.length,
          sha256: sha256Hex(PAYLOAD),
        },
      },
    }
    const out = await fetchArtifact(gone, "rtk", baseOpts(home))
    expect(out.ok === false && out.code).toBe("FETCH_FAILED")
    expect(out.ok === false && out.attempts).toBe(1)
  })

  itTls("connection refused -> NETWORK_ERROR after the single retry", async () => {
    requireFixture()
    const home = freshHome()
    const lock = fixtureLock()
    const dead: LockFile = {
      ...lock,
      components: {
        ...lock.components,
        rtk: { url: "https://127.0.0.1:1/artifact", version: "v", size: PAYLOAD.length, sha256: sha256Hex(PAYLOAD) },
      },
    }
    const out = await fetchArtifact(dead, "rtk", baseOpts(home))
    expect(out.ok === false && out.code).toBe("NETWORK_ERROR")
    expect(out.ok === false && out.attempts).toBe(2)
  })

  itTls("hanging server -> TIMEOUT once the deadline passes (both attempts share it)", async () => {
    requireFixture()
    const home = freshHome()
    const lock = fixtureLock()
    const hang: LockFile = {
      ...lock,
      components: {
        ...lock.components,
        rtk: {
          url: `https://127.0.0.1:${portOf()}/hangs`,
          version: "v",
          size: PAYLOAD.length,
          sha256: sha256Hex(PAYLOAD),
        },
      },
    }
    const out = await fetchArtifact(hang, "rtk", baseOpts(home, { timeoutMs: 100 }))
    expect(out.ok === false && out.code).toBe("TIMEOUT")
  })
})

describe("resume (P-15, §6.3) — instrumented zero-fetch", () => {
  itTls("valid file already present -> resumed with ZERO server hits", async () => {
    requireFixture()
    const home = freshHome()
    const opts = baseOpts(home)
    mkdirSync(join(home, ".swarm", "tools", "test"), { recursive: true, mode: 0o700 })
    const dest = join(home, ".swarm", "tools", "test", "artifact")
    writeFileSync(dest, PAYLOAD)
    const before = Object.entries(hits).reduce((sum, [, n]) => sum + n, 0)
    const out = await fetchArtifact(fixtureLock(), "node", { ...opts, destName: "artifact" })
    expect(out.status).toBe("resumed")
    if (out.status !== "resumed") return
    expect(out.attempts).toBe(0)
    const after = Object.entries(hits).reduce((sum, [, n]) => sum + n, 0)
    expect(after).toBe(before) // instrumented proof: the server saw NOTHING
    const prov = readProvenanceRecords(opts.provenancePath)
    expect(prov[0]?.outcome).toBe("resumed")
    expect(prov[0]?.attempts).toBe(0)
  })

  itTls("tampered prior file does NOT resume: re-downloads and replaces atomically", async () => {
    requireFixture()
    const home = freshHome()
    mkdirSync(join(home, ".swarm", "tools", "test"), { recursive: true, mode: 0o700 })
    const dest = join(home, ".swarm", "tools", "test", "artifact2")
    writeFileSync(dest, WRONG)
    const out = await fetchArtifact(fixtureLock(), "node", baseOpts(home, { destName: "artifact2" }))
    expect(out.status).toBe("fetched")
    expect(readFileSync(dest)).toEqual(PAYLOAD)
  })

  it("resume decision uses the digest, never the filename or size", () => {
    const home = freshHome()
    const p = join(home, "flip.bin")
    writeFileSync(p, PAYLOAD)
    const expected = parseExpectedDigest(sha256Hex(PAYLOAD))
    if (!expected) throw new Error("static sha256 must parse")
    expect(fileMatchesDigest(p, expected)).toBe(true)
    const flipped = Uint8Array.from(PAYLOAD)
    flipped[0] = flipped[0]! ^ 0xff // one bit flipped, same size, same name
    writeFileSync(p, flipped)
    expect(fileMatchesDigest(p, expected)).toBe(false)
    expect(computeFileDigest(p).sizeBytes).toBe(PAYLOAD.length)
  })
})

describe("macOS signature gate (§6.1 step 3, P-1)", () => {
  it("macSignatureCheck refuses a non-Mach-O file via the REAL system tools (nothing executed)", () => {
    const home = freshHome()
    const p = join(home, "not-an-app.txt")
    writeFileSync(p, "just text\n")
    const r = macSignatureCheck(p, { teamId: "ABCDE12345" })
    expect(r.codesignOk).toBe(false)
    expect(r.spctlOk).toBe(false)
  })

  itTls("signature requested -> unsigned artifact ends SIGNATURE_FAILED, final never created", async () => {
    requireFixture()
    const home = freshHome()
    const out = await fetchArtifact(
      fixtureLock(),
      "node",
      baseOpts(home, {
        signature: { run: () => ({ codesignOk: false, spctlOk: false, detail: "scripted: unsigned" }) },
      }),
    )
    expect(out.ok === false && out.code).toBe("SIGNATURE_FAILED")
    expect(existsSync(join(home, ".swarm", "tools", "test", "artifact"))).toBe(false)
    expect(stagingLeftovers(home)).toEqual([])
  })

  itTls("signature ok but TeamIdentifier mismatch -> refused (Obsidian team_id rule)", async () => {
    requireFixture()
    const home = freshHome()
    const out = await fetchArtifact(
      fixtureLock(),
      "node",
      baseOpts(home, {
        signature: {
          teamId: "REAL12345",
          run: () => ({ codesignOk: true, spctlOk: true, teamId: "FAKE67890", detail: "scripted" }),
        },
      }),
    )
    expect(out.ok === false && out.code).toBe("SIGNATURE_FAILED")
  })

  itTls("signature ok + TeamID match -> promoted", async () => {
    requireFixture()
    const home = freshHome()
    const out = await fetchArtifact(
      fixtureLock(),
      "node",
      baseOpts(home, {
        signature: {
          teamId: "REAL12345",
          run: () => ({ codesignOk: true, spctlOk: true, teamId: "REAL12345", detail: "scripted pass" }),
        },
      }),
    )
    expect(out.status).toBe("fetched")
  })
})

describe("provenance JSONL ledger", () => {
  itTls("one parseable record per settled call, with url/version/expected/observed/size/ts", async () => {
    requireFixture()
    const home = freshHome()
    const opts = baseOpts(home)
    const ok = await fetchArtifact(fixtureLock(), "node", opts)
    expect(ok.ok !== false).toBe(true)
    const bad = await fetchArtifact(fixtureLock(), "obsidian", opts) // hash mismatch
    expect(bad.ok).toBe(false)
    const prov = readProvenanceRecords(opts.provenancePath)
    expect(prov.length).toBe(2)
    expect(prov.every((r) => r !== null)).toBe(true)
    const first = prov[0] as ReturnType<typeof readProvenanceRecords>[number] & object
    expect(first.outcome).toBe("fetched")
    expect(first.lockVersion).toBe("fixture-lock-v1")
    expect(first.component).toBe("node")
    expect(first.version).toBe("v9.9.9")
    expect(first.expected).toBe(sha256Hex(PAYLOAD))
    expect(first.observed).toBe(sha256Hex(PAYLOAD))
    expect(first.downloadedBytes).toBe(PAYLOAD.length)
    expect(typeof first.ts).toBe("string")
    expect(Number.isNaN(Date.parse(first.ts))).toBe(false)
    expect(first.url).toBe(`https://127.0.0.1:${portOf()}/artifact`)
    const second = prov[1] as Record<string, unknown>
    expect(second.outcome).toBe("failed")
    expect(second.code).toBe("HASH_MISMATCH")
  })

  itTls("dry-run performs zero network, zero writes, and records nothing", async () => {
    requireFixture()
    const home = freshHome()
    const opts = baseOpts(home)
    const before = Object.entries(hits).reduce((sum, [, n]) => sum + n, 0)
    const out = await fetchArtifact(fixtureLock(), "node", { ...opts, dryRun: true })
    expect(out.status).toBe("dry_run")
    const after = Object.entries(hits).reduce((sum, [, n]) => sum + n, 0)
    expect(after).toBe(before)
    expect(existsSync(join(home, ".swarm", "tools"))).toBe(false)
    expect(readProvenanceRecords(opts.provenancePath)).toEqual([])
  })
})
